INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, 1, "", "", 3, "nyx_cmn_03", 13020022, 0.2, "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, 10, "", "", 11, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", 13020023, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 0, "", "", "", 91, "", 13020024, "", "", 302);
