INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, 10, "", "", 11, "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", 13020026, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 0, "", "", "", 91, 1, 13020027, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, 10, "", "", 11, "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", 13020028, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 0, "", "", "", 91, 1, 13020029, "", "", 302);
